const PRODUCT_IMAGE_PREFIX="supabase:product-images/";
const PRODUCT_IMAGE_MAX_BYTES=5*1024*1024;
const legacyProductImageKeys=new Set<string>(productSeed.flatMap(row=>row[5]?[row[5]]:[]));
function storagePathFromImageRef(value:string|null){return value?.startsWith(PRODUCT_IMAGE_PREFIX)?value.slice(PRODUCT_IMAGE_PREFIX.length):null}
function isValidProductImageRef(value:string|null){if(value===null)return true;if(legacyProductImageKeys.has(value))return true;const path=storagePathFromImageRef(value);return Boolean(path&&/^[a-zA-Z0-9_-]+\/[a-zA-Z0-9._-]+$/.test(path))}
function decodedBase64Size(value:string){const padding=value.endsWith("==")?2:value.endsWith("=")?1:0;return Math.floor(value.length*3/4)-padding}
function base64Prefix(value:string){const binary=atob(value.slice(0,24));return Uint8Array.from(binary,char=>char.charCodeAt(0))}
function validImageBytes(bytes:Uint8Array,mime:string){if(mime==="image/jpeg")return bytes.length>=3&&bytes[0]===0xff&&bytes[1]===0xd8&&bytes[2]===0xff;if(mime==="image/png")return bytes.length>=8&&bytes[0]===0x89&&bytes[1]===0x50&&bytes[2]===0x4e&&bytes[3]===0x47&&bytes[4]===0x0d&&bytes[5]===0x0a&&bytes[6]===0x1a&&bytes[7]===0x0a;return mime==="image/webp"&&bytes.length>=12&&String.fromCharCode(...bytes.slice(0,4))==="RIFF"&&String.fromCharCode(...bytes.slice(8,12))==="WEBP"}
async function resolveProductImageUrls(ctx:Ctx,accessToken:string,refs:Array<string|null>){const paths=[...new Set(refs.flatMap(ref=>{const path=storagePathFromImageRef(ref);return path?[path]:[]}))];if(paths.length===0)return new Map<string,string>();const result=await ctx.executePrivileged(privileged.signSupabaseProductImages,{access_token:accessToken,storage_paths:paths});return new Map(Object.entries(result.urls).map(([path,url])=>[`${PRODUCT_IMAGE_PREFIX}${path}`,url]));}
