type DemandBillRow={billId:string;outletId:string;timestamp:Date;total:number;itemQuantity:number};
function aggregateHourlyDemand(rows:DemandBillRow[]){const billsByHour=new Map<string,{outlet_id:string;timestamp:string;orders:number;units_sold:number;revenue:number;billIds:Set<string>}>();for(const row of rows){const stamp=new Date(row.timestamp);stamp.setUTCMinutes(0,0,0);const key=`${row.outletId}|${stamp.toISOString()}`;const current=billsByHour.get(key)??{outlet_id:row.outletId,timestamp:stamp.toISOString(),orders:0,units_sold:0,revenue:0,billIds:new Set<string>()};current.units_sold+=row.itemQuantity;if(!current.billIds.has(row.billId)){current.billIds.add(row.billId);current.orders+=1;current.revenue+=row.total;}billsByHour.set(key,current);}return[...billsByHour.values()].map(row=>({outlet_id:row.outlet_id,timestamp:row.timestamp,orders:row.orders,units_sold:row.units_sold,revenue:money(row.revenue),average_order_value:row.orders?money(row.revenue/row.orders):0})).sort((a,b)=>a.timestamp.localeCompare(b.timestamp));}
function staffingFor(orders:number,settings:{ordersPerStaffHour:number;staffingBufferPercent:number;minimumStaff:number;maximumStaff:number}){const base=Math.max(settings.minimumStaff,Math.ceil(orders/settings.ordersPerStaffHour));const buffered=Math.ceil(base*(1+settings.staffingBufferPercent/100));return{base_staff:Math.min(settings.maximumStaff,base),recommended_staff:Math.min(settings.maximumStaff,Math.max(settings.minimumStaff,buffered))};}

type Access={userId:string;fullName:string;email:string;role:"owner"|"manager"|"cashier";outletIds:string[];isOwner:boolean;accessToken:string};
async function getAccess(ctx:Ctx,accessToken:string):Promise<Access>{
  if(!accessToken)throw new Error("Authentication is required.");
  const verified=await ctx.executePrivileged(privileged.verifySupabaseUser,{access_token:accessToken});
  if(!verified.valid||!verified.role||!verified.is_active)throw new Error("Your RetailIQ access is inactive or has not been assigned.");
  const db=supabaseDb(ctx,accessToken);
  const outletIds=verified.role==="owner"?(await db.select({id:schema.outlets.id}).from(schema.outlets).where(eq(schema.outlets.isActive,true))).map((row:any)=>row.id as string):verified.outlet_ids;
  return{userId:verified.user_id,fullName:verified.full_name,email:verified.email,role:verified.role,outletIds,isOwner:verified.role==="owner",accessToken};
}
function canAccessOutlet(access:Access,outletId:string){return access.role==="owner"||access.outletIds.includes(outletId)}
function requireRole(access:Access,roles:Access["role"][]){if(!roles.includes(access.role))throw new Error("You do not have permission to perform this action.")}
async function logAudit(ctx:Ctx,access:Access,action:string,entityType:string,entityId:string,outletId:string|null,metadata:Record<string,unknown>={}){const db=supabaseDb(ctx,access.accessToken);await db.insert(schema.auditLogs).values({id:id("AUD"),userId:access.userId,action,entityType,entityId,outletId,metadata:JSON.stringify(metadata),createdAt:new Date()});}
